  for (let i = 0; i < text.length; i = i + 1) {
    if (text[i] === ch) {
      return i;
    }
  }
  return -1;
}
console.log(position('hello', 'l'));   // 2
console.log(position('hello', 'x'));   // -1

function firstCube(limit) {
  for (let i = 1; i <= 50; i = i + 1) {
    if (i * i * i > limit) {
      return i;
    }
  }
  return -1;
}
console.log(firstCube(20));   // 3 (27 > 20)

