function splitPair(text) {
  let dash = -1;
  for (let i = 0; i < text.length; i = i + 1) {
    if (text[i] === '-') {
      dash = i;
      break;
    }
  }
  if (dash === -1) {
    return 'Немає дефіса';
  }
  return `Ліва: ${text.slice(0, dash)}, права: ${text.slice(dash + 1)}`;
}
console.log(splitPair('ab-cd'));   // Ліва: ab, права: cd
